let audioCtx=null;const lastSfx={};function audioReady(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return null;audioCtx=audioCtx||new AC();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx;}function sfx(kind){try{const now=performance.now(),gap=kind==='hit'?90:kind==='enemy'?180:55;if(now-(lastSfx[kind]||0)<gap)return;lastSfx[kind]=now;const ac=audioReady();if(!ac)return;const t=ac.currentTime,o=ac.createOscillator(),g=ac.createGain(),settings={slash:[150,62,.14,'sawtooth',.09],shot:[520,210,.12,'triangle',.07],magic:[760,180,.28,'sine',.1],portal:[980,165,.38,'sine',.12],nature:[240,720,.42,'triangle',.11],blade:[190,52,.25,'sawtooth',.13],arrow:[920,280,.18,'triangle',.1],gold:[1150,510,.32,'sine',.11],dragon:[125,44,.48,'sawtooth',.15],hit:[105,48,.09,'square',.045],dodge:[410,900,.16,'sine',.055],enemy:[82,38,.24,'sawtooth',.07],boss:[62,28,.42,'sawtooth',.14]},v=settings[kind]||settings.hit;o.type=v[3];o.frequency.setValueAtTime(v[0],t);o.frequency.exponentialRampToValueAtTime(v[1],t+v[2]);g.gain.setValueAtTime(v[4],t);g.gain.exponentialRampToValueAtTime(.001,t+v[2]);o.connect(g).connect(ac.destination);o.start(t);o.stop(t+v[2]);}catch{}}
function roarSfx(ancient=false){try{const ac=audioReady();if(!ac)return;const now=performance.now();if(now-(lastSfx.roar||0)<350)return;lastSfx.roar=now;const t=ac.currentTime,d=ancient?1.85:1.1,master=ac.createGain(),filter=ac.createBiquadFilter(),comp=ac.createDynamicsCompressor();master.gain.setValueAtTime(.001,t);master.gain.exponentialRampToValueAtTime(ancient?.42:.27,t+.06);master.gain.setValueAtTime(ancient?.42:.27,t+d*.55);master.gain.exponentialRampToValueAtTime(.001,t+d);filter.type='lowpass';filter.frequency.setValueAtTime(1250,t);filter.frequency.exponentialRampToValueAtTime(170,t+d);comp.threshold.value=-16;comp.ratio.value=7;master.connect(filter).connect(comp).connect(ac.destination);const length=Math.ceil(ac.sampleRate*d),buffer=ac.createBuffer(1,length,ac.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++){const x=i/length,envelope=Math.sin(Math.PI*Math.min(1,x*1.7))*(1-x*.32);data[i]=(Math.random()*2-1)*envelope;}const noise=ac.createBufferSource();noise.buffer=buffer;noise.connect(master);noise.start(t);noise.stop(t+d);[ancient?78:96,ancient?46:58,ancient?116:132].forEach((f,i)=>{const o=ac.createOscillator(),g=ac.createGain();o.type=i===1?'square':'sawtooth';o.frequency.setValueAtTime(f,t);o.frequency.exponentialRampToValueAtTime(f*(i===2?.7:.5),t+d);g.gain.setValueAtTime(i===0?.17:i===1?.1:.065,t);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g).connect(master);o.start(t);o.stop(t+d);});}catch{}}
function powerSfx(p,heroIndex){if(['roar','ancientRoar','heroicRoar','skyRoar'].includes(p.id)){roarSfx(p.id==='ancientRoar'||p.id==='skyRoar');return;}sfx(['portal','nature','blade','arrow','gold','dragon'][heroIndex]||'magic');}
['pointerdown','keydown'].forEach(type=>window.addEventListener(type,audioReady,{once:true,passive:true}));
function damage(e,n){if(e.dead)return;sfx(e.boss?'boss':'hit');if(e.boss)n=Math.max(1,Math.round(n*(e.phase===0?.8:e.phase===1?.9:1)));e.hp-=n;e.flash=.12;burst(e.x,e.y,'#f9dd9c',5);effects.push({type:'number',x:e.x,y:e.y-60,text:n,color:'#fff0b5',life:.65,max:.65});if(e.hp<=0){e.dead=true;burst(e.x,e.y,'#c9f69e',18);if(!e.dummy){const reward=e.boss?25:1;coins+=reward;saveProgress();effects.push({type:'number',x:e.x,y:e.y-25,text:'+'+reward+' קאמה',color:'#f5d98d',life:1.4,max:1.4});}}}
function hurt(h,n){if(h.hp<=0||h.inv>0)return;h.hp=Math.max(0,h.hp-(h.guard>0?Math.ceil(n*.25):n));h.inv=.45;burst(h.x,h.y,'#ff9d87',6);shake=.15;if(h.hp===0)updateUI();}
function switchHero(i){if(!heroes[i]||heroes[i].hp<=0||heroes[i].locked){say(heroes[i]?.locked?'עוד לא פגשתם את אדמאי':'הדמות נחה כרגע');return;}if(i!==selected){selected=i;moveTarget=null;movePath=[];tutorial.switched=true;ring(heroes[i].x,heroes[i].y,colors[i],50);updateUI();}}
const POWER_KEYS=['E · 7','Q · 8','R · 9','F · 0','G','T','Y','E+Q','R+F','Q+R','F+G','E+F'],POWER_CODES=['KeyE','KeyQ','KeyR','KeyF','KeyG','KeyT','KeyY'];
