function activePowers(i=selected){return loadouts[i].slice(0,slotCounts[i]).map(id=>POWERS[i].find(p=>p.id===id)).filter(Boolean);}
function currentPower(i=selected,slot=0){return activePowers(i)[slot]||activePowers(i)[0];}
function updateUI(){document.querySelectorAll('.hero').forEach((b,i)=>{const fallen=heroes[i]?.hp<=0&&unlocked[i];b.classList.toggle('active',selected===i);b.classList.toggle('locked',!unlocked[i]);b.setAttribute('aria-pressed',String(selected===i));b.disabled=!unlocked[i]||fallen;b.querySelector('.health i').style.width=Math.max(0,heroes[i]?.hp??100)+'%';b.style.opacity=!unlocked[i] ? .45 : (fallen ? .4 : 1);const state=b.querySelector('.unlock-state');if(state)state.textContent=!unlocked[i]?'נפתח אחרי הבוס הראשון':fallen?'חוזרת בהרפתקה הבאה':'';});$('#coins').textContent=coins;const powers=activePowers(),key=selected+':'+powers.map(p=>p.id).join(',');if(key!==powerUiKey){powerUiKey=key;$('#powerActions').innerHTML=powers.map((p,i)=>'<button data-power-slot="'+i+'" title="'+p.name+' — '+POWER_STATS[p.id]+'" aria-label="'+p.name+' · '+POWER_KEYS[i]+'"><span>'+p.icon+'</span><b>'+p.name+'</b><kbd>'+POWER_KEYS[i]+'</kbd><i class="power-cooldown"></i></button>').join('');document.querySelectorAll('[data-power-slot]').forEach(b=>b.onclick=()=>special(+b.dataset.powerSlot));}document.querySelectorAll('[data-power-slot]').forEach((b,i)=>{const p=powers[i],cd=heroes[selected]?.cds?.[p.id]||0;b.querySelector('i').style.width=(1-cd/p.cd)*100+'%';});}
function attack(i=selected){if(!['training','battle'].includes(mode)||paused)return;const h=heroes[i];if(h.hp<=0||h.attackCd>0||h.locked)return;h.attackCd=(i===2||i===4)?.42:.52;h.anim=i===3?.65:(i===2||i===4||i===5)?.5:.38;h.animType=i===5?'breath':(i===3?'bow':(i===2||i===4?'melee':'ranged'));sfx(i===2||i===4?'slash':'shot');const e=nearest(h),a=e?Math.atan2(e.y-h.y,e.x-h.x):h.face;h.face=a;if(i===2||i===4){slash(h,a,i===4?90:105);enemies.forEach(e=>{if(dist(h,e)<(i===4?105:120))damage(e,i===2&&h.guard>0?42:i===4?25:28);});}else{const speed=i===3?620:490,dmg=i===3?26:i===5?24:i===0?20:18;shots.push({x:h.x+Math.cos(a)*(i===5?18:0),y:h.y-28,z:i===5?77:0,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:i===3?1.25:.95,color:colors[i],leaf:i===1,arrow:i===3,fire:i===5,dmg,delay:i===3?.28:0,warp:0});ring(h.x+Math.cos(a)*24,h.y-28,colors[i],24);}if(i===selected)tutorial.attack=true;}
function lineDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);}
function activateExtraPower(p,h,e,a){if(p.effect==='area'){ring(h.x,h.y,colors[heroIndexOf(h)]||'#9fefff',p.radius);burst(h.x,h.y,colors[heroIndexOf(h)]||'#9fefff',34);enemies.forEach(x=>{if(dist(h,x)<p.radius){damage(x,p.damage);if(p.root)x.root=Math.max(x.root,p.root);}});if(p.heal)heroes.filter(x=>x.hp>0&&!x.locked).forEach(x=>{x.hp=Math.min(100,x.hp+p.heal);effects.push({type:'number',x:x.x,y:x.y-65,text:'+'+p.heal,color:'#9affae',life:1,max:1});});if(p.shield)heroes.filter(x=>x.hp>0&&!x.locked).forEach(x=>{x.inv=Math.max(x.inv,p.shield);ring(x.x,x.y,'#ffe391',70);});shake=.35;return true;}if(p.effect==='volley'){const targets=enemies.filter(x=>x.hp>0);for(let k=0;k<p.count;k++){const target=targets[k%Math.max(1,targets.length)],ang=target?Math.atan2(target.y-h.y,target.x-h.x):a+(k-p.count/2)*.13;shots.push({x:h.x,y:h.y-25,vx:Math.cos(ang)*p.speed,vy:Math.sin(ang)*p.speed,life:1.45,color:colors[heroIndexOf(h)]||'#fff0a0',arrow:true,dmg:p.damage,warp:0});}return true;}if(p.effect==='snipe'){const target=enemies.filter(x=>x.hp>0).sort((x,y)=>y.hp-x.hp)[0];if(target){effects.push({type:'beam',x:h.x,y:h.y-25,tx:target.x,ty:target.y,color:colors[heroIndexOf(h)]||'#fff0a0',life:.5,max:.5});damage(target,p.damage);}return true;}const areas={riftBurst:[135,360,0,0,0,'#69efff'],thornCrown:[125,330,5,0,0,'#9cff7a'],lifeWave:[110,330,0,45,0,'#b8ff9d'],bladeRush:[150,260,0,0,0,'#ffae72'],titanStrike:[210,340,1.5,0,0,'#ff8f55'],starVolley:[145,380,0,0,0,'#ffe58a'],goldenQuake:[140,320,0,0,0,'#ffd45b'],vaultBlast:[120,330,0,0,4,'#ffe18b'],wingStorm:[150,380,0,0,0,'#a8efff'],ancientRoar:[100,400,6,0,0,'#bcefff'],dragonNova:[180,420,0,0,4,'#d8fbff']},volleys={timeFold:[10,42,680,'#6eeaff',false],arrowCyclone:[10,40,760,'#f8e79d',true],magnetCoins:[8,44,620,'#ffd65c',false]};if(areas[p.id]){const [dmg,r,root,heal,shield,color]=areas[p.id];ring(h.x,h.y,color,r);burst(h.x,h.y,color,40);enemies.forEach(x=>{if(dist(h,x)<r){damage(x,dmg);if(root)x.root=Math.max(x.root,root);}});if(heal)heroes.filter(x=>x.hp>0&&!x.locked).forEach(x=>{x.hp=Math.min(100,x.hp+heal);effects.push({type:'number',x:x.x,y:x.y-65,text:'+'+heal,color:'#9affae',life:1,max:1});});if(shield)heroes.filter(x=>x.hp>0&&!x.locked).forEach(x=>{x.inv=shield;ring(x.x,x.y,color,72);});shake=.45;return true;}if(volleys[p.id]){const [count,dmg,speed,color,arrow]=volleys[p.id],targets=enemies.filter(x=>x.hp>0);for(let k=0;k<count;k++){const target=targets[k%Math.max(1,targets.length)],ang=target?Math.atan2(target.y-h.y,target.x-h.x):a+(k-count/2)*.12;shots.push({x:h.x,y:h.y-25,vx:Math.cos(ang)*speed,vy:Math.sin(ang)*speed,life:1.45,color,arrow,dmg,warp:0});}ring(h.x,h.y,color,180);return true;}if(p.id==='hunterMark'){const target=enemies.filter(x=>x.hp>0).sort((x,y)=>y.hp-x.hp)[0];if(target){effects.push({type:'beam',x:h.x,y:h.y-25,tx:target.x,ty:target.y,color:'#fff2a0',life:.55,max:.55});damage(target,230);}return true;}return false;}
