function openCustomParty(){let panel=$('#customOverlay');if(!panel){panel=document.createElement('div');panel.id='customOverlay';panel.className='overlay';document.body.appendChild(panel);}panel.hidden=false;panel.innerHTML='<article class="custom-card"><button id="closeCustom" class="custom-close" aria-label="סגירה">✕</button><div class="eyebrow">אתם גיבורי הסיפור</div><h2>הכניסו את עצמכם למשחק</h2><p>בחרו שמות ותמונות. התמונות נשארות רק בדפדפן הזה.</p><div class="custom-players"><label><b>שחקנית או שחקן 1</b><input id="customName1" maxlength="18" placeholder="השם שלי"><input id="customPhoto1" type="file" accept="image/*"><span>בחירת תמונה</span></label><label><b>שחקנית או שחקן 2</b><input id="customName2" maxlength="18" placeholder="השם השני"><input id="customPhoto2" type="file" accept="image/*"><span>בחירת תמונה</span></label></div><button id="saveCustom" class="primary">להכניס אותנו למשחק ←</button></article>';$('#customName1').value=customParty[0]?.name||'';$('#customName2').value=customParty[1]?.name||'';$('#closeCustom').onclick=()=>{panel.hidden=true;canvas.focus();};$('#saveCustom').onclick=async()=>{const photos=await Promise.all([avatarFromFile($('#customPhoto1').files[0]),avatarFromFile($('#customPhoto2').files[0])]);customParty=[{name:$('#customName1').value.trim(),photo:photos[0]||customParty[0]?.photo||''},{name:$('#customName2').value.trim(),photo:photos[1]||customParty[1]?.photo||''}];try{localStorage.setItem('wakfu-custom-party',JSON.stringify(customParty));}catch{}refreshCustomParty();panel.hidden=true;say('אתם עכשיו בתוך החבורה!');canvas.focus();};}
