function resumeAuto(){if(autoPaused&&paused){autoPaused=false;pauseGame();}}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyW','KeyA','KeyS','KeyD'].includes(e.code)){resumeAuto();moveTarget=null;movePath=[];}keys.add(e.code);if(e.repeat)return;if(/^Digit[1-6]$/.test(e.code))switchHero(Number(e.code.slice(-1))-1);const numberSlot=NUMBER_POWER_CODES.indexOf(e.code);if(numberSlot>=0)special(numberSlot);if(e.code==='KeyJ')attack();const comboSlot=POWER_COMBOS.findIndex(combo=>combo.every(code=>keys.has(code)));if(comboSlot>=0){POWER_COMBOS[comboSlot].forEach(code=>comboUsed.add(code));special(7+comboSlot);}else{const powerSlot=POWER_CODES.indexOf(e.code);if(powerSlot>=4)special(powerSlot);}if(e.code==='Space')dodge();if(e.code==='KeyB')openShop();if(e.code==='KeyP'||e.code==='Escape'){if(!$('#shopOverlay').hidden)closeShop();else{autoPaused=false;pauseGame();}}});window.addEventListener('keyup',e=>{const slot=POWER_CODES.indexOf(e.code);if(slot>=0&&slot<4&&!comboUsed.has(e.code))special(slot);comboUsed.delete(e.code);keys.delete(e.code);});window.addEventListener('blur',()=>{keys.clear();comboUsed.clear();});
canvas.addEventListener('pointerdown',e=>{resumeAuto();if(!['battle','training'].includes(mode)||paused)return;const rect=canvas.getBoundingClientRect(),h=heroes[selected];let p;if(cameraMode==='firstPerson'){h.face+=(e.clientX-rect.left-rect.width/2)/rect.width*1.5;const distance=180+(1-(e.clientY-rect.top)/rect.height)*520;p={x:h.x+Math.cos(h.face)*distance,y:h.y+Math.sin(h.face)*distance};}else p={x:(e.clientX-rect.left)*devicePixelRatio/camera.scale+camera.ox,y:(e.clientY-rect.top)*devicePixelRatio/camera.scale+camera.oy};bound(p);const dry=nearestLandPoint(p);if(!dry){say('אין דרך פנויה ליעד הזה');return;}if(dist(p,dry)>12)say('היעד חסום — מחפש דרך פנויה');aim={...dry};moveTarget={...dry};movePath=findLandPath(h,dry);if(!movePath.length&&dist(h,dry)>40){moveTarget=null;say('אין מסלול פנוי. נסי לבחור מעבר או דרך אחרת');}canvas.focus();});
document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>switchHero(Number(b.dataset.hero)));document.querySelectorAll('[data-move]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();resumeAuto();moveTarget=null;movePath=[];b.setPointerCapture(e.pointerId);keys.add(b.dataset.move);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.move);});$('#attack').onclick=()=>attack();$('#dodge').onclick=dodge;$('#pause').onclick=()=>{autoPaused=false;pauseGame();};$('#resume').onclick=()=>{if(paused)pauseGame();autoPaused=false;canvas.focus();};$('#start').onclick=startTraining;$('#shopButton').onclick=openShop;$('#customButton').onclick=openCustomParty;$('#viewMode').onclick=()=>{cameraMode=cameraMode==='firstPerson'?'topDown':'firstPerson';moveTarget=null;movePath=[];document.querySelector('.arena').classList.toggle('first-person',cameraMode==='firstPerson');$('#viewMode').textContent=cameraMode==='firstPerson'?'▦ מבט מלמעלה':'👁 מבט מהעיניים';$('#viewMode').title=cameraMode==='firstPerson'?'החלפה למבט מלמעלה':'החלפה למבט מהעיניים';canvas.focus();};
$('#help').onclick=()=>{if(!['training','battle'].includes(mode))return;const wasPaused=paused;paused=true;showPanel('איך משחקים?','חצים, WASD או לחיצה על הקרקע — תנועה<br>J — תקיפה · E, Q, R, F, G, T, Y — כוחות מצוידים<br>7, 8, 9, 0 — ארבעת הכוחות הראשונים · צירופי האותיות מפעילים את מקומות 8–12<br>רווח — התחמקות · 1 עד 6 — החלפה<br>B — חנות הכוחות · P — עצירה<br><br>קני מקומות בחנות כדי להחזיק כמה כוחות יחד.<br>האזור האדום מסמן מתקפת בוס — צאי ממנו בזמן!','חזרה למשחק',()=>{$('#overlay').hidden=true;paused=wasPaused;canvas.focus();});};
reset();requestAnimationFrame(frame);
window.gameState=()=>({mode,paused,selected,coins,equipped:[...equipped],loadouts:loadouts.map(x=>[...x]),slotCounts:[...slotCounts],owned:owned.map(x=>[...x]),unlocked:[...unlocked],cameraMode,world:{width:W,height:H,area:wave},heroes:heroes.map(h=>({name:h.name,hp:h.hp,x:h.x,y:h.y,locked:h.locked,onWater:isWater(h.x,h.y),onBlocked:isBlocked(h.x,h.y)})),enemies:enemies.length,enemiesOnWater:enemies.filter(e=>isWater(e.x,e.y)).length,enemiesBlocked:enemies.filter(e=>isBlocked(e.x,e.y)).length,navigation:{target:moveTarget,pathPoints:movePath.length,audit:navigationAudit},performance:{fps:Math.round(fpsSmooth),particles:particles.length,effects:effects.length,shots:shots.length},powersPerHero:POWERS.map(p=>p.length),wave,portals:portals?{a:portals.a,b:portals.b,remaining:portals.life}:null,tutorial:{...tutorial}});
if(document.modelContext?.registerTool){for(const tool of [{name:'read_game_state',description:'Read game phase, hero positions, health, coins, equipped powers, unlocked heroes and portal positions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.gameState()},{name:'select_hero',description:'Select an unlocked party hero numbered 1 to 6.',inputSchema:{type:'object',properties:{hero:{type:'integer',minimum:1,maximum:6}},required:['hero'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Number.isInteger(input.hero)||input.hero<1||input.hero>6)throw Error('Hero must be between 1 and 6');switchHero(input.hero-1);return window.gameState();}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
